import os
import time
from configparser import ConfigParser
from IQData.utils.datetime_func import timestamp_to_time
from IQCommon.logger import system_log
root_path = os.path.dirname(__file__).split('manager')[0]
module_path_dict = {'basic_data': os.path.join(root_path, 'data_file'), 'history_data': os.path.join(root_path, 'tests', 'testdatas', 'bcolz')}
cp = ConfigParser()
cp.read(os.path.join(root_path, 'manager', 'path.cfg'), encoding='UTF-8')
class DataInfoManager(object):
    __doc__ = """
    数据信息管理器类
    """
    @staticmethod
    def get_file_size(file_path):
        if not os.path.exists(file_path):
            system_log.error('文件路径{}不存在.错误位置:data_info_manager模块下的get_file_size方法'.format(os.path.abspath(file_path)))
            raise FileNotFoundError('文件路径{}不存在'.format(os.path.abspath(file_path)))
        file_size = os.path.getsize(file_path)
        return file_size
    @staticmethod
    def get_folder_size(folder_path):
        if not os.path.exists(folder_path):
            system_log.error('文件路径{}不存在.错误位置:data_info_manager模块下的get_folder_size方法'.format(os.path.abspath(folder_path)))
            raise FileNotFoundError('文件路径{}不存在'.format(os.path.abspath(folder_path)))
        folder_size = 0
        for root, dirs, files in os.walk(folder_path):
            folder_size += sum([DataInfoManager.get_file_size(os.path.join(root, name)) for name in files])
        return folder_size
    @staticmethod
    def convert_size_with_unit(size):
        if size / 1024 < 1:
            return f"{'%.1f' % size!s}{'B'!s}"
        elif size / 1024 / 1024 < 1:
            return f"{'%.1f' % float(size / 1024)!s}{'KB'!s}"
        elif size / 1024 / 1024 / 1024 < 1:
            return f"{'%.1f' % float(size / 1024 / 1024)!s}{'MB'!s}"
        else:
            return f"{'%.1f' % float(size / 1024 / 1024 / 1024)!s}{'GB'!s}"
    @staticmethod
    def get_file_update_time(file_path):
        if not os.path.exists(file_path):
            system_log.error('文件路径{}不存在.错误位置:data_info_manager模块下的get_file_update_time方法'.format(os.path.abspath(file_path)))
            raise FileNotFoundError('文件路径{}不存在'.format(os.path.abspath(file_path)))
        timestamp = os.path.getmtime(file_path)
        update_time = timestamp_to_time(timestamp)
        return update_time
    def get_basic_data_info(self):
        files_info_dict = {}
        module_path = module_path_dict['basic_data']
        section_bd = cp.sections()[0]
        system_log.info(section_bd)
        file_name_list = []
        for file_name in cp.options(section_bd):
            file_name_list.append(cp.get(section_bd, file_name))
        for file_name in file_name_list:
            file_info_dict = dict()
            file_path = os.path.join(module_path, file_name)
            file_info_dict['file_path'] = file_path
            if os.path.isdir(file_path):
                folder_size = self.get_folder_size(file_path)
                file_info_dict['file_size'] = self.convert_size_with_unit(folder_size)
            else:
                file_size = self.get_file_size(file_path)
                file_info_dict['file_size'] = self.convert_size_with_unit(file_size)
            file_info_dict['file_update_time'] = self.get_file_update_time(file_path)
            files_info_dict[file_name] = file_info_dict
        return files_info_dict
    def get_history_data_info(self):
        files_info_dict = {}
        module_path = module_path_dict['history_data']
        section_hd = cp.sections()[1]
        file_data_dict = dict()
        for file_data in cp.options(section_hd):
            values = cp.get(section_hd, file_data)
            split = values.split(',')
            file_data_dict[file_data] = split
        for file_data in file_data_dict:
            data_info_dict = dict()
            file_path_list = file_data_dict[file_data]
            file_paths = [os.path.join(module_path, file_path) for file_path in file_path_list]
            data_info_dict['file_path'] = file_paths
            folder_size = 0
            for file in file_paths:
                folder_size += self.get_folder_size(file)
            data_info_dict['file_size'] = self.convert_size_with_unit(folder_size)
            file_update_time_list = []
            for file in file_paths:
                file_update_time = self.get_file_update_time(file)
                file_update_time_list.append(file_update_time)
            data_info_dict['file_update_time'] = max(file_update_time_list)
            files_info_dict[file_data] = data_info_dict
        return files_info_dict
